+function testLightningcssVisitorDuringMinify() {
+  let mediaQueryVisits = 0
+
+  return {
+    name: 'test-lightningcss-visitor-during-minify',
+    apply: 'build',
+    config() {
+      return {
+        css: {
+          lightningcss: {
+            visitor: {
+              MediaQuery(query) {
+                mediaQueryVisits++
+                return query
+              },
+            },
+          },
+        },
+      }
+    },
+    generateBundle() {
+      this.emitFile({
+        type: 'asset',
+        fileName: 'media-query-visits.txt',
+        source: String(mediaQueryVisits),
+      })
+    },
+  }
+}

